 t=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated'/sys.argv[2]/'summary.json';s=json.loads(src.read_text());orig=json.loads((REPO/s['source']['path']).read_text());p=np.load(REPO/orig['problem']['path']);E=p['E'];eq=np.isfinite(p['upper'])&(p['lower']==p['upper']);checks={};records=[]
 for row in s['batches']:
  c=np.load(REPO/row['output']['path']);a=np.load(REPO/row['source']['path']);y=c['y'];g=a['small_S']@y-a['small_h'];active=a['active'];mask=~eq[active];conversion=float(a['small_unit'])/a['small_row_scale']/E[active];sl=-conversion*g;dual=E[active]*a['small_row_scale']*float(a['small_unit'])*y;free=~mask|(y<-1e-10);k=max(float(np.max(abs(g[free]))),float(np.max(np.maximum(g[~free],0))) if np.any(~free) else 0.);pr=max(float(np.max(np.maximum(-sl[mask],0))),float(np.max(abs(sl[~mask]))));co=float(np.max(abs(sl[mask]*dual[mask])));sign=float(np.max(np.maximum(dual[mask],0)));bad=-y;bg=a['small_S']@bad-a['small_h'];bsl=-conversion*bg;bad_sign=float(np.max(np.maximum(-dual[mask],0)));bad_pr=max(float(np.max(np.maximum(-bsl[mask],0))),float(np.max(abs(bsl[~mask]))));omit=int(np.argmax(abs(dual)));oy=y.copy();oy[omit]=0.;og=a['small_S']@oy-a['small_h'];omission=float(np.max(abs(og-g)));wrong_rhs=float(np.max(abs(a['small_S']@y+a['small_h'])));local=dict(input_hash=sha(REPO/row['source']['path'])==row['source']['SHA256'],output_hash=sha(REPO/row['output']['path'])==row['output']['SHA256'],original_S=np.array_equal(a['small_S'],c['S']),original_h=np.array_equal(a['small_h'],c['h']),all_original_active_ids=np.array_equal(active,c['active']),original_cone_mask=np.array_equal(mask,c['inequality']),original_small_KKT=k<1e-8,original_unit_slack=pr<1e-10,original_unit_sign=sign<1e-8,original_unit_complementarity=co<1e-8,wrong_dual_sign_rejected=bad_sign>1e-8 or bad_pr>1e-10,omitted_original_row_rejected=omission>1e-8,wrong_affine_RHS_rejected=wrong_rhs>1e-8);checks['batch'+str(row['batch'])]=all(local.values());records.append(dict(batch=row['batch'],checks={k:bool(v) for k,v in local.items()},small_KKT=k,generated_row_primal_mm=pr,search_sign_N=sign,search_complementarity_Nmm=co,wrong_sign_primal_mm=bad_pr,wrong_sign_dual_N=bad_sign,omitted_original_row=int(active[omit]),omission_gradient_defect=omission,wrong_affine_gradient_defect=wrong_rhs))
